package com.anpahn.staffguard.service;
import com.anpahn.staffguard.database.Database; import com.anpahn.staffguard.util.SecurityUtil; import java.util.*; import java.util.concurrent.*;
public final class TrustedIpService {private final Database db;private final String secret;private final int max;private final ConcurrentHashMap<UUID,Set<String>> cache=new ConcurrentHashMap<>();public TrustedIpService(Database db,String secret,int max){this.db=db;this.secret=secret;this.max=max;}public CompletableFuture<Void> load(Collection<UUID> uuids){return CompletableFuture.allOf(uuids.stream().map(u->db.loadTrustedIps(u).thenAccept(s->{Set<String>x=ConcurrentHashMap.newKeySet();x.addAll(s);cache.put(u,x);})).toArray(CompletableFuture[]::new));}public String hash(String ip){return SecurityUtil.hmacSha256Hex(secret,ip);}public CompletableFuture<Boolean> isTrusted(UUID u,String ip){String h=hash(ip);Set<String>s=cache.get(u);if(s!=null)return CompletableFuture.completedFuture(s.contains(h));return db.loadTrustedIps(u).thenApply(x->{cache.put(u,ConcurrentHashMap.newKeySet());cache.get(u).addAll(x);return x.contains(h);});}public CompletableFuture<Boolean> add(UUID u,String ip){String h=hash(ip);return db.addTrustedIpHash(u,h,System.currentTimeMillis(),max).thenCompose(ok->db.loadTrustedIps(u)).thenApply(s->{cache.put(u,ConcurrentHashMap.newKeySet());cache.get(u).addAll(s);return true;});}
public void markTrustedHash(UUID u,String ipHash){cache.computeIfAbsent(u,k->ConcurrentHashMap.newKeySet()).add(ipHash);}
public CompletableFuture<Boolean> remove(UUID u,String ip){String h=hash(ip);return db.removeTrustedIp(u,h).thenApply(ok->{Set<String>s=cache.get(u);if(s!=null)s.remove(h);return ok;});}}
